sys_script_include.script:
var LeaveUtils = Class.create();
LeaveUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	initialize: function() {},
	// 给销假申请返回原请假单的核心信息
	getLeaveInfoForCancel: function() {
		var leaveSysId = this.getParameter('sysparm_leave_sysid');
		if(!leaveSysId) return null;
		// 读取原请假单数据	
		var gr = new GlideRecord('x_1973840_leave_per_leave');
		if(!gr.get(leaveSysId)) return null;

		// 返回取得的信息
		var leaveInfo = {
			sys_id: gr.sys_id.toString(),
			leave_date_start: gr.leave_date_start.toString(),
			leave_date_end: gr.leave_date_end.toString()
		};
		return JSON.stringify(leaveInfo);	
	},


    type: 'LeaveUtils'
});
